use split_decls_genesis :: ourprelude :: * ; use crate :: pin :: Pin ; #[doc = " The result of a coroutine resumption."] #[doc = ""] #[doc = " This enum is returned from the `Coroutine::resume` method and indicates the"] #[doc = " possible return values of a coroutine. Currently this corresponds to either"] #[doc = " a suspension point (`Yielded`) or a termination point (`Complete`)."] #[derive (Clone , Copy , PartialEq , PartialOrd , Eq , Ord , Debug , Hash)] #[lang = "coroutine_state"] #[unstable (feature = "coroutine_trait" , issue = "43122")] pub enum CoroutineState < Y , R > { #[doc = " The coroutine suspended with a value."] #[doc = ""] #[doc = " This state indicates that a coroutine has been suspended, and typically"] #[doc = " corresponds to a `yield` statement. The value provided in this variant"] #[doc = " corresponds to the expression passed to `yield` and allows coroutines to"] #[doc = " provide a value each time they yield."] Yielded (Y) , #[doc = " The coroutine completed with a return value."] #[doc = ""] #[doc = " This state indicates that a coroutine has finished execution with the"] #[doc = " provided value. Once a coroutine has returned `Complete` it is"] #[doc = " considered a programmer error to call `resume` again."] Complete (R) , } #[doc = " The trait implemented by builtin coroutine types."] #[doc = ""] #[doc = " Coroutines are currently an"] #[doc = " experimental language feature in Rust. Added in [RFC 2033] coroutines are"] #[doc = " currently intended to primarily provide a building block for async/await"] #[doc = " syntax but will likely extend to also providing an ergonomic definition for"] #[doc = " iterators and other primitives."] #[doc = ""] #[doc = " The syntax and semantics for coroutines is unstable and will require a"] #[doc = " further RFC for stabilization. At this time, though, the syntax is"] #[doc = " closure-like:"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(coroutines)]"] #[doc = " #![feature(coroutine_trait)]"] #[doc = " #![feature(stmt_expr_attributes)]"] #[doc = ""] #[doc = " use std::ops::{Coroutine, CoroutineState};"] #[doc = " use std::pin::Pin;"] #[doc = ""] #[doc = " fn main() {"] #[doc = "     let mut coroutine = #[coroutine] || {"] #[doc = "         yield 1;"] #[doc = "         \"foo\""] #[doc = "     };"] #[doc = ""] #[doc = "     match Pin::new(&mut coroutine).resume(()) {"] #[doc = "         CoroutineState::Yielded(1) => {}"] #[doc = "         _ => panic!(\"unexpected return from resume\"),"] #[doc = "     }"] #[doc = "     match Pin::new(&mut coroutine).resume(()) {"] #[doc = "         CoroutineState::Complete(\"foo\") => {}"] #[doc = "         _ => panic!(\"unexpected return from resume\"),"] #[doc = "     }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " More documentation of coroutines can be found in the [unstable book]."] #[doc = ""] #[doc = " [RFC 2033]: https://github.com/rust-lang/rfcs/pull/2033"] #[doc = " [unstable book]: ../../unstable-book/language-features/coroutines.html"] #[lang = "coroutine"] #[unstable (feature = "coroutine_trait" , issue = "43122")] #[fundamental] #[must_use = "coroutines are lazy and do nothing unless resumed"] pub trait Coroutine < R = () > { #[doc = " The type of value this coroutine yields."] #[doc = ""] #[doc = " This associated type corresponds to the `yield` expression and the"] #[doc = " values which are allowed to be returned each time a coroutine yields."] #[doc = " For example an iterator-as-a-coroutine would likely have this type as"] #[doc = " `T`, the type being iterated over."] #[lang = "coroutine_yield"] type Yield ; #[doc = " The type of value this coroutine returns."] #[doc = ""] #[doc = " This corresponds to the type returned from a coroutine either with a"] #[doc = " `return` statement or implicitly as the last expression of a coroutine"] #[doc = " literal. For example futures would use this as `Result<T, E>` as it"] #[doc = " represents a completed future."] #[lang = "coroutine_return"] type Return ; #[doc = " Resumes the execution of this coroutine."] #[doc = ""] #[doc = " This function will resume execution of the coroutine or start execution"] #[doc = " if it hasn't already. This call will return back into the coroutine's"] #[doc = " last suspension point, resuming execution from the latest `yield`. The"] #[doc = " coroutine will continue executing until it either yields or returns, at"] #[doc = " which point this function will return."] #[doc = ""] #[doc = " # Return value"] #[doc = ""] #[doc = " The `CoroutineState` enum returned from this function indicates what"] #[doc = " state the coroutine is in upon returning. If the `Yielded` variant is"] #[doc = " returned then the coroutine has reached a suspension point and a value"] #[doc = " has been yielded out. Coroutines in this state are available for"] #[doc = " resumption at a later point."] #[doc = ""] #[doc = " If `Complete` is returned then the coroutine has completely finished"] #[doc = " with the value provided. It is invalid for the coroutine to be resumed"] #[doc = " again."] #[doc = ""] #[doc = " # Panics"] #[doc = ""] #[doc = " This function may panic if it is called after the `Complete` variant has"] #[doc = " been returned previously. While coroutine literals in the language are"] #[doc = " guaranteed to panic on resuming after `Complete`, this is not guaranteed"] #[doc = " for all implementations of the `Coroutine` trait."] #[lang = "coroutine_resume"] fn resume (self : Pin < & mut Self > , arg : R) -> CoroutineState < Self :: Yield , Self :: Return > ; } #[unstable (feature = "coroutine_trait" , issue = "43122")] impl < G : ? Sized + Coroutine < R > , R > Coroutine < R > for Pin < & mut G > { type Yield = G :: Yield ; type Return = G :: Return ; fn resume (mut self : Pin < & mut Self > , arg : R) -> CoroutineState < Self :: Yield , Self :: Return > { G :: resume ((* self) . as_mut () , arg) } } #[unstable (feature = "coroutine_trait" , issue = "43122")] impl < G : ? Sized + Coroutine < R > + Unpin , R > Coroutine < R > for & mut G { type Yield = G :: Yield ; type Return = G :: Return ; fn resume (mut self : Pin < & mut Self > , arg : R) -> CoroutineState < Self :: Yield , Self :: Return > { G :: resume (Pin :: new (& mut * self) , arg) } }